  <BIBL><TITLE>Janii &amp; Tremellii Biblia cum Annotationibus</TITLE></BIBL>;
  <BIBL><TITLE>Acta Eruditorum Lipsiensia</TITLE> de An. <YEAR>1738</YEAR> &amp; <YEAR>1739</YEAR></BIBL>;
